34	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
35	  values.reduce((total, value) => total + amount(value), 0);
36	
37	const PROCESSING_FEE = 5;
38	
39	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
40	
41	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
42	  sword: 100,
43	  amulet: 60,
44	  staff: 80,
45	  potion: 40,
46	  rune: 25,
47	  moonstone: 25,
48	};
49	
50	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
51	
52	const BLOCK_SIZE = 3;
53	
54	const BLOCK_BASE_PREMIUM = 60;
55	
56	const basePremiumForGroup = (group: Item[]): number =>
57	  group.length === BLOCK_SIZE
58	    ? BLOCK_BASE_PREMIUM
59	    : sumBy(group, itemBasePremium);
60	
61	const sameTypeGroups = (items: Item[]): Item[][] => {
62	  const types = [...new Set(items.map((item) => item.type))];
63	  return types.map((type) => items.filter((item) => item.type === type));
64	};
65	
66	const quotePremium = (step: QuoteStep): number => {
67	  const policyBasePremium = sumBy(sameTypeGroups(step.items), basePremiumForGroup);
68	  const firstInsuranceSurcharge =
69	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
70	  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
71	};
72	
73	export const runScenario = (scenario: Scenario): ScenarioResult => ({
74	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
75	});
